def write(path,rows):
    path.parent.mkdir(parents=True,exist_ok=True)
    with path.open('w',newline='',encoding='utf-8-sig') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def preserve(path,rows,key,fields):
    if path.exists():
        with path.open(newline='',encoding='utf-8-sig') as f:old={r[key]:r for r in csv.DictReader(f)}
        for r in rows:
            for field in fields:
                if r[key] in old and old[r[key]].get(field,'')!='':r[field]=old[r[key]][field]
